window.RG = window.RG || {};
var RG = window.RG;

/* Big glossary: key words defined two ways.
   "legal" = the forensic / transactional framework common in popular evangelical and Reformed
   teaching (God as Judge, sin as guilt, the cross as payment, salvation as acquittal), stated
   in its best form. "relational" = the union / Trinitarian / restorative reading used across
   this app. This file defines terms; RG.compare (compare.js) compares practices and doctrines. */

RG.bigGlossary = [
  // ================================================================ SIN & FALL
  {
    id: "sin",
    term: "Sin",
    group: "Sin & Fall",
    legal: "Sin is any lack of conformity to, or transgression of, the law of God (Westminster Shorter Catechism, Q.14; compare 1 John 3:4). Because the law expresses God’s own holy character, every sin is an offence against God himself, bringing real guilt and deserving his just punishment. Sin is not a small mistake: it is rebellion of the creature against the Creator, and it must be dealt with legally before a sinner can stand before a holy Judge; for that reason the legal gospel begins with the bad news of guilt, so that the good news of pardon will be understood and treasured.",
    relational: "Sin is first a <em>condition</em> before it is a list of acts: missing the mark of the life of love we were made for, and so falling short of the glory of God (Rom 3:23). It is like a disease or a slavery that blinds us, twists our desires and breaks our relationships with God, ourselves, each other and creation (Rom 7:14-24). God is not the injured party who needs to be paid back; he is the Physician who comes to heal the sick (Mark 2:17). So sin is serious precisely because it destroys the people God loves, and his answer is to defeat it, not merely to punish it, and the cure he brings reaches every part of the wound, from the guilt we feel to the habits that bind us and the relationships we have broken.",
    original: "Hebrew <em>chata’</em> (חָטָא), “to miss” (used of slingers who did not miss the target, Judg 20:16); <em>‘avon</em> (עָוֹן), iniquity, twistedness; <em>pesha‘</em> (פֶּשַׁע), rebellion. Greek <em>hamartia</em> (ἁμαρτία), which Thayer’s lexicon glosses as “a failing to hit the mark”; Paul often pictures it as a power that “reigns” (Rom 5:21; 6:12). The Greek Old Testament (Septuagint) normally renders <em>chata’</em> with <em>hamartanō</em>, so the New Testament word carries the whole Hebrew picture of missing the way, twisting the road and rebelling against the covenant Lord.",
    refs: ["Rom 3:23", "Rom 5:12", "Rom 6:12-14", "Rom 7:14-24", "1 John 3:4", "Mark 2:17", "Gen 4:7", "John 8:34-36"],
    note: "Both views agree sin is deadly serious; the real debate is whether its deepest problem is guilt before a court (legal) or bondage and sickness that alienate us from Love (relational), and most of the Bible uses both pictures."
  },
  {
    id: "the-fall",
    term: "The Fall",
    group: "Sin & Fall",
    legal: "The Fall is the historical event in which Adam, as the covenant head of the human race, broke God’s command in Eden (Gen 2:17; 3:6). By that one act the whole race fell into a state of sin and misery, losing original righteousness and coming under God’s curse and condemnation (Rom 5:18). Everything wrong in the world, from death to broken relationships, flows from this first disobedience, which is why the legal gospel insists that every human being needs a Saviour, not merely better teaching or a better example.",
    relational: "The Fall is humanity turning from trusting the Father’s love to grasping at life on its own terms, believing the lie that God was holding something back (Gen 3:4-5). It did not change God’s heart toward us; it changed our <em>perception</em> of him, so that we began to hide from the One who still came walking in the garden looking for us (Gen 3:8-9). Irenaeus pictured Adam and Eve as immature children who were meant to grow up into God’s likeness, so the Fall interrupted a story of growth rather than ending a finished perfection. Christ, the Last Adam, steps into the fallen human story and carries it to its intended goal (1 Cor 15:22, 45), so that what was lost in Adam is not only restored but surpassed in the risen Son.",
    original: "The Bible never uses the word “Fall” for Genesis 3. Paul speaks of Adam’s <em>parabasis</em> (παράβασις, “transgression, stepping over a line”, Rom 5:14) and <em>paraptōma</em> (παράπτωμα, “false step, trespass”, Rom 5:15-18). The English phrase reflects later Latin theological language, such as <em>lapsus</em>, “a slip, a falling”, for Adam’s sin.",
    refs: ["Gen 3:1-24", "Gen 2:17", "Rom 5:12-21", "1 Cor 15:21-22", "1 Cor 15:45-49", "Gen 3:8-9"],
    note: "Christians disagree about how literally to read Genesis 3 (a single historical pair, a representative story, or both), but both frameworks agree that humanity as a whole is caught up in a real alienation it cannot undo by itself."
  },
  {
    id: "what-happened-at-the-fall",
    term: "What happened at the Fall",
    group: "Sin & Fall",
    legal: "At the Fall humanity incurred guilt before God, and a legal sentence was passed: death, curse, expulsion from the garden and, ultimately, eternal condemnation (Gen 3:17-19; Rom 5:16). Fellowship with God was broken from God’s side as well as ours, because a holy God cannot simply overlook rebellion (Hab 1:13). Humanity’s nature also became corrupt, so that people are now unable to please God by their own power (Rom 8:7-8), and so they need both a new legal standing and a new heart.",
    relational: "Genesis 3 describes what happened in very relational terms: eyes opened to shame, fig leaves, hiding, fear and blame (Gen 3:7-13). The first words of the fallen man are “I was afraid… so I hid myself” (Gen 3:10), and the first words of God are a question of seeking love: “Where are you?” (Gen 3:9). Death, toil and pain are pictured as the consequences of stepping out of the flow of God’s life, more like a branch cut off from the vine than a judge passing a sentence (John 15:4-6). God himself clothes them with skins (Gen 3:21) and promises a Seed who will crush the serpent (Gen 3:15), so grace is present at the very scene of the Fall, and even the guarding of the tree of life is framed as mercy, so that humanity would not live forever in a fallen state (Gen 3:22-24).",
    original: "Hebrew <em>‘arom</em> (“naked”, Gen 2:25) is a wordplay with <em>‘arum</em> (“crafty”, Gen 3:1) for the serpent. God’s question “Where are you?” is <em>’ayyekkah</em> (אַיֶּכָּה), a single word of seeking. The Hebrew of Gen 3:7 says their eyes “were opened”, the very thing the serpent promised (3:5), but what they saw was not divinity but their own exposure.",
    refs: ["Gen 3:7-13", "Gen 3:15", "Gen 3:21", "Gen 3:22-24", "Rom 8:7-8", "Rom 8:20-21"],
    note: "Readers differ on whether the curses of Genesis 3:14-19 are penalties God imposes or descriptions of what life outside trust becomes; many interpreters, ancient and modern, hold that they are both."
  },
  {
    id: "original-sin",
    term: "Original sin",
    group: "Sin & Fall",
    legal: "In the Reformed tradition, original sin means that Adam’s guilt is imputed (credited) to all his descendants, and that every human being inherits a corrupt nature from conception (Ps 51:5; Rom 5:12-19). The Westminster Confession says that the guilt of Adam’s sin “was imputed” and that a “corrupted nature” was “conveyed to all their posterity” (WCF 6.3). This explains why all people sin and why infants also need the grace of Christ, and it is why the legal gospel holds that no one is innocent before God apart from Christ.",
    relational: "We are born into a fallen world and inherit its brokenness: mortality, fear, a bent toward self-protection and a distorted picture of God. But many in the relational stream, following the Eastern church, distinguish inheriting the <em>consequences</em> of Adam’s sin (especially death) from inheriting Adam’s personal <em>guilt</em>. Death came to all, and through fear of death we became slaves to sin (Heb 2:14-15; Rom 5:12). And the deeper truth is that Christ is more “original” than Adam: humanity was chosen in him “before the foundation of the world” (Eph 1:4), so original sin is never deeper than original belovedness, and the Last Adam is stronger than the first, for “where sin abounded, grace abounded much more” (Rom 5:20).",
    original: "The phrase is Latin, <em>peccatum originale</em>, developed especially by Augustine. In Romans 5:12 the Greek <em>eph’ hō</em> (ἐφ’ ᾧ) is usually translated “because” (all sinned), but the Latin Vulgate rendered it <em>in quo</em> (“in whom”), which shaped the Western reading. Eastern Christians generally prefer the term “ancestral sin” (Greek <em>propatorikē hamartia</em>) to describe the inherited condition without inherited personal guilt.",
    refs: ["Rom 5:12-19", "Ps 51:5", "Eph 2:3", "Heb 2:14-15", "Eph 1:4", "1 Cor 15:22"],
    note: "The Orthodox Church in America explains that while everyone bears the consequences of the first sin, “only Adam and Eve are guilty of that sin”, which is a real difference from the Augustinian and Reformed view of imputed guilt."
  },
  {
    id: "law",
    term: "Law",
    group: "Sin & Fall",
    legal: "God’s law is the perfect expression of his righteous will, summarised in the Ten Commandments and binding on all people (Rom 2:14-15). The law has three uses in Reformed teaching: it restrains evil in society, it shows sinners their guilt and drives them to Christ (Gal 3:24), and it guides believers in grateful obedience. No one can be justified by keeping it, because everyone has broken it (Gal 3:10-11), and so the law that condemns also points the guilty sinner toward the only One who kept it perfectly.",
    relational: "<em>Torah</em> means instruction or teaching, the loving guidance of a covenant God for a people he had already rescued (Exod 20:2). It was a tutor or guardian until Christ came (Gal 3:24-25), a shadow of the reality that is Christ himself (Col 2:17; Heb 10:1). Jesus fulfils it and sums it up in love of God and neighbour (Matt 22:37-40; Rom 13:10), and the Spirit now writes it on hearts (Jer 31:33; 2 Cor 3:3). The law was never the way into relationship with God; it was a description of life inside that relationship, which is why Paul can say that love is the fulfilling of the law.",
    original: "Hebrew <em>torah</em> (תּוֹרָה), “instruction, teaching”, from a root associated with pointing or directing. Greek <em>nomos</em> (νόμος), “law, custom”. Paul’s <em>paidagōgos</em> (Gal 3:24) was the household slave who supervised a child until adulthood, not a teacher in the modern sense. The Septuagint usually translated <em>torah</em> with <em>nomos</em>, which some scholars think narrowed the warmer sense of “instruction” into “law”, though <em>nomos</em> could also mean a whole way of life.",
    refs: ["Exod 20:1-17", "Gal 3:10-11", "Gal 3:24-25", "Rom 13:10", "Matt 5:17-18", "Jer 31:33", "Col 2:16-17"],
    note: "The division of the Law into moral, civil and ceremonial parts is a later Christian categorisation (Aquinas, Calvin); Jewish tradition counts 613 commandments without that split, so both camps should hold the categories loosely."
  },
  {
    id: "works-based-salvation",
    term: "Works-based salvation",
    group: "Sin & Fall",
    legal: "Works-based salvation is the false belief that a person can earn or contribute to their standing with God through moral effort, religious ritual or law-keeping. The Reformers saw it in medieval merit, indulgences and penance, and they answered with “faith alone” and “grace alone” (Eph 2:8-9; Rom 4:4-5). Any mixture of human merit with Christ’s work, the legal view warns, empties the cross of its power (Gal 2:21), so the legal gospel guards fiercely against any teaching that adds human effort to the finished work of Christ.",
    relational: "Earning is a mindset of distance: it assumes God is far away and must be persuaded, appeased or paid. The relational gospel agrees that we cannot earn God, but adds that the legal gospel can quietly become works-based too, when faith, a prayer, a decision or ongoing performance becomes the transaction that unlocks God’s love. The good news is that God has already acted in Christ while we were still sinners (Rom 5:8); our works are fruit of union, not the price of it (John 15:5). Good works matter enormously, but as the life of a child at home, not wages of a servant (Luke 15:29-31), and like the older brother in the parable, the one who works for wages can live in the Father’s house without ever enjoying the Father’s love.",
    original: "Paul’s phrase <em>erga nomou</em> (ἔργα νόμου), “works of the law” (Rom 3:28; Gal 2:16). Scholars of the “New Perspective on Paul” (E.P. Sanders, James Dunn, N.T. Wright) argue it refers especially to Jewish boundary markers such as circumcision, food laws and Sabbath, not to moral effort in general; others strongly disagree. Paul’s opposite to “works of the law” is <em>akoē pisteōs</em> (ἀκοὴ πίστεως, Gal 3:2, 5), “the hearing of faith”: receiving a message rather than achieving a result.",
    refs: ["Eph 2:8-10", "Rom 4:4-5", "Gal 2:16", "Gal 2:21", "Rom 11:6", "Luke 15:29-31", "Titus 3:5"],
    note: "What Paul meant by “works of the law” is one of the liveliest debates in modern New Testament study, and both frameworks can affirm that salvation is a gift that produces, rather than depends on, good works."
  },
  {
    id: "death",
    term: "Death",
    group: "Sin & Fall",
    legal: "Death is the wages of sin and the just penalty God pronounced on Adam and his race (Gen 2:17; Rom 6:23). It has three aspects: spiritual death (separation from God now), physical death (separation of soul and body) and eternal death (final separation from God in hell). Christ died in the sinner’s place so that believers would be spared eternal death, and the believer can face physical death with hope because its sting, sin under the law, has been removed.",
    relational: "Death is the enemy, not God’s friend or tool (1 Cor 15:26). It is the unravelling that happens when creatures step out of the flow of God’s life, and the fear of it keeps humanity enslaved (Heb 2:14-15). Athanasius taught that the Word took a body so that, dying in it, he might undo death from inside human nature and give it incorruption (<em>On the Incarnation</em>). Christ does not save us from God; he saves us from death, by entering it and rising, so that death has lost its sting (1 Cor 15:54-57), and so for those in Christ death is no longer a sentence to be feared but a doorway through which the risen Lord walks with us.",
    original: "Hebrew <em>mavet</em> (מָוֶת), death; Greek <em>thanatos</em> (θάνατος). Paul personifies death as a reigning tyrant (Rom 5:14, 17) and the “last enemy” (1 Cor 15:26). Paul calls believers who have died “those who have fallen asleep” (<em>koimaō</em>, κοιμάω, 1 Thess 4:13-14), a gentle word that points to waking in resurrection.",
    refs: ["Rom 6:23", "1 Cor 15:26", "1 Cor 15:54-57", "Heb 2:14-15", "Rom 5:12-17", "Gen 2:17", "Rev 21:4"],
    note: "Both views agree that death is linked to sin and conquered by Christ; they differ on whether it is chiefly a sentence God imposes or a corruption God overcomes, and on whether the “death” of Gen 2:17 means physical death, spiritual death, or both."
  },
  {
    id: "satan",
    term: "Satan",
    group: "Sin & Fall",
    legal: "Satan is a real, personal fallen angel, the chief enemy of God and of his people, who tempts, deceives and accuses (1 Pet 5:8; Rev 12:9-10). He holds no rights over God, but he enslaves sinners who remain under God’s just condemnation, and he uses the law’s accusation against them. On the cross Christ cancelled the record of debt, so Satan can no longer successfully accuse those who believe (Col 2:14-15), and he will finally be cast into the lake of fire when Christ returns (Rev 20:10).",
    relational: "Satan is the accuser and the liar, whose oldest work is to slander God’s character and humanity’s identity (Gen 3:1-5; John 8:44). His power is largely the power of deception and fear, which is why the cross exposes and disarms him by revealing what God is truly like (Col 2:15; Heb 2:14). The early church loved to speak of Christ’s victory over the powers (<em>Christus Victor</em>), and the relational gospel stresses that God and Satan are not two equal forces, nor partners in punishing humanity: the accuser has been “thrown down” (Rev 12:10). We resist him by standing in the truth of who God is and who we are in Christ (Eph 6:10-17; Jas 4:7), knowing that the accuser’s voice is not the Father’s voice, and that there is “no condemnation for those who are in Christ Jesus” (Rom 8:1).",
    original: "Hebrew <em>satan</em> (שָׂטָן), “adversary, accuser”; in Job 1–2 it appears with the article, <em>ha-satan</em>, “the accuser”. Greek <em>diabolos</em> (διάβολος), “slanderer”, from <em>diaballō</em>, to throw across, to slander. Revelation 12:10 calls him “the accuser of our brothers”, using <em>katēgōr</em> (κατήγωρ), a courtroom word for a prosecutor, which shows that accusation itself is pictured as his work, not God’s.",
    refs: ["Gen 3:1-5", "John 8:44", "Col 2:14-15", "Heb 2:14-15", "Rev 12:9-11", "1 John 3:8", "Jas 4:7"],
    note: "Some early fathers spoke of a “ransom” paid to the devil, a picture later writers such as Gregory of Nazianzus rejected; today both views generally reject the idea that God owed Satan anything."
  },

  // ================================================================ HUMANITY
  {
    id: "humanity",
    term: "Humanity",
    group: "Humanity",
    legal: "Human beings are creatures made by God, accountable to him as Lawgiver and Judge, and created upright but now fallen. Since the Fall every person is a sinner by nature and by choice, “dead in trespasses” and under condemnation until they are converted (Eph 2:1-3). Human dignity remains because we still bear God’s image, but in our natural state we are separated from God, and their greatest need is to be reconciled to the God they have offended.",
    relational: "Humanity is God’s beloved creation, made by Father, Son and Spirit to share in their life of love (Gen 1:26-27; John 17:21-23). Our deepest identity is not defined by the Fall but by Christ, in whom all things were created and in whom all things hold together (Col 1:16-17). The Son became human and so united himself with every human being, which is why the church fathers could say that he became what we are so that we might become what he is (Irenaeus, <em>Against Heresies</em> 5, preface). People are not first “sinners in the hands of an angry God” but children who have forgotten whose they are (Luke 15:17), and the gospel is the Father running to meet them while they are still a long way off (Luke 15:20).",
    original: "Hebrew <em>’adam</em> (אָדָם), “human, humankind”, a wordplay with <em>’adamah</em> (אֲדָמָה), “ground, soil” (Gen 2:7). Greek <em>anthrōpos</em> (ἄνθρωπος), “human being”. Paul’s contrast between “the first man Adam” and “the last Adam” (1 Cor 15:45) treats Christ as the true and representative human in whom humanity is remade.",
    refs: ["Gen 1:26-27", "Gen 2:7", "Ps 8:3-6", "Col 1:16-17", "Eph 2:1-3", "Acts 17:28", "Luke 15:17"],
    note: "The difference here is mostly about starting point: the legal view begins with what humanity became in Adam, the relational view with what humanity is in Christ, and both affirm that both truths are in the Bible."
  },
  {
    id: "image-of-god",
    term: "The image of God",
    group: "Humanity",
    legal: "The image of God is what sets humans apart from the animals: rationality, moral awareness, the capacity to know God and the call to rule creation on his behalf (Gen 1:26-28). Reformed theology teaches that the image was marred but not erased by the Fall, which is why human life remains sacred (Gen 9:6; Jas 3:9). In salvation the image is renewed in knowledge, righteousness and holiness (Col 3:10; Eph 4:24), so that believers increasingly reflect God’s character in their thinking, choices and relationships.",
    relational: "We are made in the image of a God who is relationship, so the image is not only a set of abilities but a way of being: made for love, communion and self-giving (Gen 1:27; 1 John 4:8). Christ is <em>the</em> image of the invisible God (Col 1:15), and we were made in his pattern, so to see what humanity truly is we look at Jesus. Irenaeus and others distinguished the image (given) from the likeness (grown into), so salvation is the restoring and maturing of the image until we share God’s life (2 Cor 3:18). The image was never lost; it was buried, and the gospel uncovers it, and every person we meet, however broken, still carries that buried glory.",
    original: "Hebrew <em>tselem</em> (צֶלֶם), “image, statue, representation” and <em>demut</em> (דְּמוּת), “likeness” (Gen 1:26). In the ancient Near East a king set up his <em>tselem</em> to mark his rule. Greek <em>eikōn</em> (εἰκών), “image” (Col 1:15). Gen 1:27 uses the image for “male and female” together, so many interpreters see the image as reflected in relationship and community, not only in individual capacities.",
    refs: ["Gen 1:26-28", "Gen 9:6", "Ps 8:5", "Col 1:15", "2 Cor 3:18", "2 Cor 4:4", "Col 3:10", "Jas 3:9"],
    note: "Many Hebrew scholars think <em>tselem</em> and <em>demut</em> in Gen 1:26 are near-synonyms, so Irenaeus’s image/likeness distinction is a fruitful theological reading rather than a strict lexical one."
  },
  {
    id: "spirit",
    term: "Spirit (human spirit)",
    group: "Humanity",
    legal: "The human spirit is the immaterial part of a person by which they relate to God; many evangelicals treat “spirit” and “soul” as two names for the same inner self, while others distinguish them (1 Thess 5:23; Heb 4:12). Through sin the spirit is dead toward God, and in regeneration the Holy Spirit makes it alive (Eph 2:1, 5). The Spirit then bears witness with our spirit that we are God’s children (Rom 8:16), which gives believers the assurance that they truly belong to him.",
    relational: "Spirit is breath, the life of God breathed into dust (Gen 2:7; Job 33:4). The human spirit is our capacity for communion, the place where “deep calls to deep” (Ps 42:7) and where the Holy Spirit and our spirit become one in Christ (1 Cor 6:17). The relational gospel stresses that this union is God’s gift, not our achievement, and that it reaches out into the whole person: mind, emotions and body. Being “spiritual” therefore does not mean escaping the body, but living the whole of life in the flow of God’s breath (Gal 5:25), so prayer, work, rest and meals can all become places where the Spirit is breathing in us.",
    original: "Hebrew <em>ruach</em> (רוּחַ), “breath, wind, spirit”; Greek <em>pneuma</em> (πνεῦμα), with the same range (John 3:8 plays on “wind” and “Spirit”). The same Hebrew word is used for the Spirit hovering over the waters (Gen 1:2) and the breath that comes into the dry bones (Ezek 37:9-10), linking human life closely to God’s own creative breath.",
    refs: ["Gen 2:7", "Job 33:4", "John 3:8", "Rom 8:16", "1 Cor 6:17", "1 Thess 5:23", "Gal 5:25"],
    note: "Whether humans are two-part (body and soul/spirit) or three-part (body, soul and spirit) is debated within both frameworks; Hebrew thought tends to see the person as a whole rather than as separable parts."
  },
  {
    id: "soul",
    term: "Soul",
    group: "Humanity",
    legal: "The soul is the immortal, immaterial part of a person that survives death and will face God’s judgment (Matt 10:28; Heb 9:27). Evangelism is therefore often described as “saving souls”, because the eternal destiny of the soul is at stake. At death the souls of believers go immediately into the presence of Christ, awaiting the resurrection of the body (Phil 1:23; 2 Cor 5:8), which is why the legal gospel urges people to settle the question of their soul’s eternal destiny now, while there is time.",
    relational: "In Hebrew thinking the soul is not a spark trapped inside a body but the whole living person: Adam did not <em>receive</em> a soul, he <em>became</em> a living soul (Gen 2:7). The soul is our life, desires, emotions and self, and Jesus came to save the whole person, not to extract a soul from a body. The relational gospel therefore resists any gospel that “rescues the soul while leaving the body behind”, and looks for the healing of minds, hearts, bodies and relationships (3 John 2; 1 Thess 5:23). The soul finds its rest only in communion with God (Ps 62:1; Matt 11:29), and Jesus’ invitation is that we will find “rest for our souls” in him.",
    original: "Hebrew <em>nephesh</em> (נֶפֶשׁ), “living being, life, self, appetite”, sometimes even “throat” (Isa 5:14). Greek <em>psychē</em> (ψυχή), “life, self, soul”, which Jesus uses when he speaks of losing and finding one’s life (Mark 8:35). In the Hebrew Bible animals are also called <em>nephesh chayyah</em>, “living beings” (Gen 1:24), the same phrase used for Adam in Gen 2:7, which shows that the word means life rather than an immortal part as such.",
    refs: ["Gen 2:7", "Matt 10:28", "Mark 8:35-36", "Ps 62:1", "Matt 11:29", "3 John 2", "1 Thess 5:23"],
    note: "The idea of a naturally immortal soul owes much to Greek philosophy; some evangelicals (conditional immortalists) and many relational writers stress instead that immortality is God’s gift in Christ (1 Tim 6:16; 2 Tim 1:10)."
  },
  {
    id: "body",
    term: "Body",
    group: "Humanity",
    legal: "The body is part of God’s good creation and will be raised at the last day, but in this life it is weak, mortal and the arena where sin tempts us (Rom 6:12; 1 Cor 9:27). Believers are to honour God with their bodies, which are temples of the Holy Spirit (1 Cor 6:19-20). Popular evangelical teaching has often emphasised the soul’s salvation and treated the body chiefly as something to discipline, so that the body becomes a servant of righteousness rather than a slave to its appetites.",
    relational: "The body is not a souvenir of Adam but a sanctuary for Christ. God formed it from the dust with his own hands (Gen 2:7), the Son took a human body forever (John 1:14), rose bodily and ascended as a man (Luke 24:39), and the Spirit dwells in our bodies now (1 Cor 6:19). Salvation is embodied: Jesus healed bodies as a sign of the kingdom, and our future is not escape from the body but its resurrection and glorification (Rom 8:11, 23; Phil 3:21). So caring for, honouring and expressing faith through the body is part of the gospel, not a distraction from it, and that includes rest, healthy touch, sleep, food, play and healing as gifts God gives to embodied children.",
    original: "Greek <em>sōma</em> (σῶμα), “body”, is good and redeemable; <em>sarx</em> (σάρξ), “flesh”, in Paul often means human life oriented away from God, not the physical body as such (Gal 5:16-17). Hebrew <em>basar</em> (בָּשָׂר), “flesh”, can mean all human beings (Joel 2:28). Paul’s phrase “spiritual body” (<em>sōma pneumatikon</em>, 1 Cor 15:44) means a body fully animated by the Spirit, not a body made of spirit.",
    refs: ["Gen 2:7", "John 1:14", "Luke 24:39", "1 Cor 6:19-20", "Rom 8:11", "Rom 8:23", "Phil 3:21", "Rom 12:1"],
    note: "Reading Paul’s “flesh” (<em>sarx</em>) as if it meant the physical body has caused much body-shame in church history; both frameworks officially affirm the goodness of the body and the bodily resurrection."
  },

  // ================================================================ GOD & CHRIST
  {
    id: "gospel",
    term: "Gospel",
    group: "God & Christ",
    legal: "The gospel is the good news of how guilty sinners can be made right with a holy God: Christ died for our sins, bearing their penalty, and rose again, so that all who repent and believe are forgiven and declared righteous (1 Cor 15:3-4; Rom 3:21-26). It is often summarised as God, man, Christ, response. Without the bad news of sin and judgment, the legal view insists, the good news makes no sense, because the cross is only good news to those who know they need rescue.",
    relational: "The gospel is the announcement of what God has done in Jesus: the Son of the Father has become one of us, lived our life, died our death, defeated sin and death, risen and ascended, and so has reconciled the world to God (2 Cor 5:19; Col 1:19-20). It is the gospel of the kingdom (Mark 1:14-15) and the good news that Jesus is Lord, which Paul preached as an accomplished fact to be believed, not a deal to be accepted. It is not first “how to get to heaven” but “who God is, who you are, and what he has done for all”. Response matters deeply, but the news is true before we believe it; believing is waking up to it (Luke 15:24), like a son coming to his senses and finding his father already running toward him.",
    original: "Greek <em>euangelion</em> (εὐαγγέλιον), “good news, good announcement”, used in the Roman world for news of victories and imperial births (for example the Priene calendar inscription about Augustus). Hebrew <em>basar</em> (בָּשַׂר), “to bring good news” (Isa 52:7). Mark opens with “the beginning of the gospel of Jesus Christ, the Son of God” (Mark 1:1), which suggests that the whole story of Jesus, not only a summary formula, is the gospel.",
    refs: ["Mark 1:14-15", "1 Cor 15:1-8", "Rom 1:1-4", "Rom 1:16-17", "2 Cor 5:18-20", "Isa 52:7", "Luke 2:10-11"],
    note: "C.H. Dodd (<em>The Apostolic Preaching and Its Developments</em>, 1936) and Scot McKnight (<em>The King Jesus Gospel</em>, 2011) both argued that the apostolic gospel was the story of Jesus as Messiah and Lord, a point many evangelicals now also affirm."
  },
  {
    id: "kingdom",
    term: "Kingdom",
    group: "God & Christ",
    legal: "The kingdom of God is God’s sovereign rule, which is entered by being born again and which will come in fullness at Christ’s return (John 3:3; Matt 25:34). In popular evangelical teaching the kingdom is often closely tied to heaven and the future, while in the present it is mainly the spiritual reign of Christ in believers’ hearts and in the church. Social good is welcome, but the church’s first task is to call people into the kingdom through conversion, and so evangelism is the church’s first contribution to the kingdom’s growth.",
    relational: "The kingdom is the reign of God’s love breaking into this world in Jesus: the blind see, the lame walk, the poor hear good news and enemies are forgiven (Luke 4:18-19; Matt 11:5). Jesus announced it as “at hand” and taught us to pray for it to come “on earth as it is in heaven” (Mark 1:15; Matt 6:10). It is already present wherever God’s will is done, and it will be complete when God is “all in all” (1 Cor 15:28). It is not only a place we go when we die but a life we live now: righteousness, peace and joy in the Holy Spirit (Rom 14:17), so its signs today are healed bodies, reconciled enemies, shared bread and lives set free.",
    original: "Greek <em>basileia</em> (βασιλεία), “reign, rule, kingship” more than a territory; Hebrew <em>malkut</em> (מַלְכוּת). Matthew mostly says “kingdom of heaven”, a reverent Jewish way of saying “kingdom of God”, not a different kingdom located in the sky. Jesus’ phrase “the kingdom of God is in your midst” (Luke 17:21) translates <em>entos hymōn</em> (ἐντὸς ὑμῶν), which can mean “within you” or “among you”, and translators are divided.",
    refs: ["Mark 1:14-15", "Matt 6:10", "Luke 4:18-19", "Luke 17:20-21", "Rom 14:17", "1 Cor 15:24-28", "Col 1:13"],
    note: "Scholars widely agree the kingdom is “already and not yet”; the frameworks differ on emphasis, with the relational view stressing its present, earthly and healing reality."
  },
  {
    id: "the-bible",
    term: "The Bible",
    group: "God & Christ",
    legal: "The Bible is the inspired, inerrant and authoritative Word of God, the final rule for all faith and life (2 Tim 3:16-17). Every part is equally God’s Word and must be harmonised with every other part; texts on God’s wrath stand alongside texts on his love without one correcting the other. Believers read it to know sound doctrine, obey God’s commands and grow in faith, and its clear teaching settles disputes about doctrine and life.",
    relational: "The Bible is the God-breathed, trustworthy witness to the living Word, Jesus Christ (John 5:39-40; Heb 1:1-3). Jesus is the lens through which the whole of Scripture is read, since he said the Scriptures “testify about me” and opened the disciples’ minds to see himself in them (Luke 24:27, 44-45). This is sometimes called a Christ-centred or cruciform reading: where a passage seems to picture God unlike Jesus, we ask how the cross reveals what was really going on. The Bible is less a rule book dropped from heaven than a family story that climaxes in Jesus, inspired by the Spirit and still alive (Heb 4:12), so that reading it becomes an encounter with a Person rather than only a search for rules.",
    original: "English “Bible” comes from Greek <em>ta biblia</em> (τὰ βιβλία), “the books”. Paul calls Scripture <em>theopneustos</em> (θεόπνευστος), “God-breathed” (2 Tim 3:16). Hebrews 4:12 calls God’s word <em>zōn</em> (ζῶν), “living”, and <em>energēs</em> (ἐνεργής), “active, at work”, from which English gets “energy”.",
    refs: ["2 Tim 3:16-17", "John 5:39-40", "Luke 24:27", "Luke 24:44-45", "Heb 1:1-3", "John 1:1-14", "Heb 4:12"],
    note: "Both frameworks hold Scripture as inspired; the debate is about method, especially whether Jesus should be used as an interpretive key that relativises violent portrayals of God (Greg Boyd, Brad Jersak) or whether all texts must be held in flat harmony."
  },
  {
    id: "grace",
    term: "Grace",
    group: "God & Christ",
    legal: "Grace is God’s unmerited favour toward sinners who deserve his wrath: he gives them the righteousness and salvation they could never earn (Eph 2:8-9; Rom 3:24). It is often summarised as “God’s Riches At Christ’s Expense”. Reformed theology adds that saving grace is effectual: God’s grace does not merely make salvation possible but actually brings the elect to faith, and the one God draws by grace will certainly come to him (John 6:37, 44).",
    relational: "Grace is God giving himself: not a substance or a credit but the Father’s love poured out in the Son and the Spirit, the very life of God shared with us (John 1:14-17; 2 Pet 1:4). Grace was not a plan B after the Fall; it is who God has always been, “given us in Christ Jesus before times eternal” (2 Tim 1:9). Grace forgives, but it also heals, empowers and trains us in a new way of life (Titus 2:11-12), and it is for all people (Titus 2:11). We do not earn it, and we do not have to unlock it; we receive it and live from it, so that grace becomes the air we breathe rather than a reward we chase.",
    original: "Greek <em>charis</em> (χάρις), “favour, gift, kindness, thanks”, related to <em>chara</em>, joy. Hebrew <em>chen</em> (חֵן), “favour”, and <em>chesed</em> (חֶסֶד), God’s steadfast covenant love, a word with no exact English equivalent. Paul opens almost every letter with “grace and peace” (<em>charis</em> and <em>eirēnē</em>), joining a Greek greeting to the Hebrew <em>shalom</em>.",
    refs: ["Eph 2:4-10", "John 1:14-17", "Rom 3:24", "Rom 5:20-21", "2 Tim 1:9", "Titus 2:11-14", "2 Cor 12:9"],
    note: "Critics of “hyper-grace” teaching worry that it makes grace an excuse for sin; relational teachers answer with Titus 2:11-12, that the same grace that saves also trains us to say no to ungodliness."
  },
  {
    id: "atonement",
    term: "Atonement",
    group: "God & Christ",
    legal: "The atonement is the work of Christ on the cross by which he satisfied God’s justice and turned away his wrath by bearing the penalty for sin in the sinner’s place (penal substitution, Isa 53:5-6; Rom 3:25-26). In this view God’s holiness requires that sin be punished, and in love God himself provides the substitute (1 John 4:10). Penal substitution is regarded by many evangelicals as the heart of the gospel, though they usually also affirm other aspects such as victory and example, while holding that Christ’s bearing of sin’s penalty is what makes those other aspects possible.",
    relational: "Atonement means at-one-ment: God making humanity one with himself again. It began in the Incarnation, when the Son joined God and humanity in his own person, continued through his whole obedient life, and was completed in his death, resurrection and ascension (Heb 2:14-17). On the cross Christ entered our sin, alienation and death, and defeated them from the inside, healing human nature (Isa 53:5; 2 Cor 5:21). The cross does not change God’s mind about us; it reveals God’s heart and changes us (Rom 5:8-10), and Athanasius could say that the Word became human so that humanity might be made divine.",
    original: "English “atonement” was formed from “at-one-ment” and popularised by William Tyndale. Hebrew <em>kaphar</em> / <em>kippur</em> (כָּפַר), usually “to cover” or “to wipe clean, purge” (meaning debated). Greek <em>hilastērion</em> (ἱλαστήριον, Rom 3:25), used in Heb 9:5 for the “mercy seat”, and <em>hilasmos</em> (ἱλασμός, 1 John 2:2), translated either “propitiation” or “expiation”. On the Day of Atonement (<em>Yom Kippur</em>, Lev 16) one goat was offered and the other, the scapegoat, carried Israel’s sins away into the wilderness, which shows that the Old Testament itself used more than one picture of atonement.",
    refs: ["Isa 53:4-6", "Rom 3:25-26", "Rom 5:8-11", "2 Cor 5:18-21", "Heb 2:14-17", "1 John 2:2", "1 John 4:10", "Lev 16:15-22"],
    note: "The church has never defined one official theory of atonement; Christus Victor, recapitulation, ransom, satisfaction, moral influence and penal substitution all have defenders, and many theologians see them as facets of one jewel."
  },
  {
    id: "the-cross",
    term: "The cross",
    group: "God & Christ",
    legal: "The cross is where Jesus, the sinless substitute, bore the full weight of God’s judgment against sin, so that God could be both “just and the justifier” of those who believe (Rom 3:26). Christ became a curse for us (Gal 3:13), and the Father laid on him the iniquity of us all (Isa 53:6). The cross is therefore the place where divine justice and divine love meet: sin is truly punished, and sinners are truly spared, and so the cross is the only safe refuge for sinners before a holy God.",
    relational: "The cross is the clearest revelation of what God is like: self-giving, enemy-forgiving love (John 12:32; Rom 5:8). There God in Christ entered the depths of human sin, violence and abandonment, crying the human cry of Psalm 22, and forgave his killers as he died (Luke 23:34). The cross exposes the powers of religion and empire that killed him and disarms them (Col 2:15), and it shows that God would rather suffer violence than inflict it. It is not the Father punishing the Son, but the Father, Son and Spirit together bearing our sin to heal it, for “God was in Christ reconciling the world to himself” (2 Cor 5:19), and the One lifted up on the cross is drawing all people to himself (John 12:32).",
    original: "Greek <em>stauros</em> (σταυρός), “upright stake, cross”. The apostles also call it <em>xylon</em> (ξύλον), “tree, wood” (Acts 5:30; 1 Pet 2:24), echoing Deut 21:23, “cursed is everyone who hangs on a tree” (Gal 3:13). Paul calls his message <em>ho logos ho tou staurou</em> (ὁ λόγος ὁ τοῦ σταυροῦ), “the word of the cross” (1 Cor 1:18), foolishness to the world but God’s power to those being saved.",
    refs: ["John 12:31-33", "Rom 5:8", "2 Cor 5:19-21", "Col 2:13-15", "Gal 3:13", "Luke 23:34", "Phil 2:5-8", "1 Cor 1:18-25"],
    note: "Both views see the cross as central; the dispute is whether Christ was punished by the Father in our place or bore our sin and its consequences in solidarity with us, and Jesus’ cry of forsakenness (Mark 15:34) is read differently by each."
  },
  {
    id: "the-blood",
    term: "The blood",
    group: "God & Christ",
    legal: "“The blood of Christ” refers to his sacrificial death, which fulfils the Old Testament sacrifices and pays the price for sin, since “without shedding of blood there is no remission” (Heb 9:22). His blood propitiates God’s wrath, cleanses the believer’s guilt and purchases the church (Acts 20:28; Rom 5:9). Evangelical hymns sing of being “washed in the blood” as the only ground of forgiveness, and believers can plead the blood with confidence that their guilt has been fully dealt with.",
    relational: "In the Bible, blood is life: “the life of the flesh is in the blood” (Lev 17:11). So the blood of Christ is his very life, poured out for us and given to us to share (John 6:53-56). It cleanses not by appeasing God but by purifying our conscience and bringing us near (Heb 9:14; Eph 2:13). Abel’s blood cried out for vengeance, but Jesus’ blood “speaks better things” (Heb 12:24): mercy, peace and a new covenant (Luke 22:20), which is why Jesus gives us his blood in the cup to drink rather than only to admire.",
    original: "Hebrew <em>dam</em> (דָּם) and Greek <em>haima</em> (αἷμα), “blood”. Lev 17:11 links blood with <em>nephesh</em>, life: blood is the life given back to God in the offerings. Jesus’ words “this cup is the new covenant in my blood” (Luke 22:20; 1 Cor 11:25) echo Exod 24:8, where Moses sprinkled “the blood of the covenant” to seal Israel’s relationship with God.",
    refs: ["Lev 17:11", "Heb 9:14", "Heb 9:22", "Heb 12:24", "Eph 2:13", "Col 1:20", "John 6:53-56", "Luke 22:20"],
    note: "Scholars debate whether Old Testament sacrifice was primarily about substitution and penalty or about purification and life given to God; both meanings have been defended from the text."
  },
  {
    id: "wrath",
    term: "Wrath",
    group: "God & Christ",
    legal: "God’s wrath is his holy, settled, personal opposition to sin, the necessary response of perfect justice to evil (Rom 1:18; John 3:36). It is not a loss of temper but the action of retributive justice against those who deserve condemnation, and it is fully consistent with his love. The good news is that Christ bore this wrath on the cross, so that believers are “saved from wrath through him” (Rom 5:9), and the believer who is in Christ will never face it.",
    relational: "God’s wrath is real, but it is the wrath of love against what destroys the beloved, like a parent’s fury at the cancer killing their child. In Romans 1, wrath is described as God “giving people over” to the consequences of their own choices (Rom 1:24, 26, 28). Brad Jersak and others describe it as the intrinsic consequence of refusing mercy, not an urge to retaliate. Wrath is never the last word: God’s anger lasts “for a moment”, his favour for a lifetime (Ps 30:5), and his purpose even in judgment is to heal (Hos 6:1; Lam 3:31-33), and in Christ we see that his anger is always aimed at sin, death and the powers, never at the people he made and loves.",
    original: "Greek <em>orgē</em> (ὀργή), “anger, wrath”, and <em>thymos</em> (θυμός), “passion, rage”. Hebrew <em>’aph</em> (אַף), literally “nostril”, used for burning anger, and <em>charon</em> (חָרוֹן), “burning”. The phrase “the wrath of God” in Romans is often impersonal (literally “the wrath”, <em>hē orgē</em>, Rom 5:9; 12:19), which C.H. Dodd took as a sign of an inevitable process of cause and effect, a reading others contest.",
    refs: ["Rom 1:18-28", "John 3:36", "Rom 5:9", "Ps 30:5", "Lam 3:31-33", "Hos 11:8-9", "Eph 2:3-5"],
    note: "Both frameworks agree that a God who did not oppose evil would not be good; they differ on whether wrath is retributive (legal) or restorative and consequential (relational)."
  },

  // ================================================================ SALVATION
  {
    id: "salvation",
    term: "Salvation",
    group: "Salvation",
    legal: "Salvation is God’s rescue of sinners from the penalty, power and finally the presence of sin, and above all from his righteous wrath and eternal punishment (Rom 5:9; 1 Thess 1:10). It is received by grace through faith in Christ, at a definite moment of conversion (Eph 2:8). Its past, present and future aspects are justification, sanctification and glorification, and these are inseparable, since all whom God justifies he will also glorify (Rom 8:30).",
    relational: "Salvation is being healed, made whole and brought into the life of the Trinity. The same Greek word means “save”, “heal” and “make well” (Mark 5:34), so salvation includes forgiveness, freedom, healing of the heart and body, restored relationships and finally resurrection. Its source is the Incarnation, in which the Son united himself to humanity, and its goal is that we “become partakers of the divine nature” (2 Pet 1:4), what the Eastern church calls theosis. It is not God saving us from himself, but God saving us from sin, death and the lies that kept us from him (Heb 2:14-15), so salvation is the story of humanity finally coming fully alive.",
    original: "Hebrew <em>yeshu‘ah</em> (יְשׁוּעָה), “deliverance, salvation”, the root of the name <em>Yeshua</em>, Jesus (Matt 1:21). Greek <em>sōtēria</em> (σωτηρία), which Strong’s glosses as “rescue or safety (physically or morally)”; the verb <em>sōzō</em> (σῴζω) is used both for being saved and for being healed. Zacchaeus heard “Today salvation has come to this house” (Luke 19:9) at a shared meal and a changed economic life, showing how concrete and relational the word is in Luke.",
    refs: ["Mark 5:34", "Luke 19:9-10", "Eph 2:8-10", "2 Pet 1:4", "Rom 8:29-30", "Phil 2:12-13", "Titus 3:4-7"],
    note: "Many Christians, East and West, describe salvation in past, present and future tenses; the frameworks differ on whether the central danger saved from is God’s wrath or the corruption of sin and death."
  },
  {
    id: "repentance",
    term: "Repentance",
    group: "Salvation",
    legal: "Repentance is a grace by which a sinner, seeing their sin and God’s mercy in Christ, grieves over and hates their sins and turns from them to God, resolving to obey him (WCF 15.2 summarised). It is a necessary condition of receiving forgiveness and the inseparable companion of saving faith (Acts 2:38; 20:21). Without repentance, the legal view warns, a profession of faith is empty, because true faith always turns away from sin as it turns toward Christ.",
    relational: "Repentance is a change of mind: seeing God, ourselves and others in a new light, and turning around to come home (Luke 15:17-20). It is not penance to earn forgiveness but the response to love already given, for “the kindness of God leads you to repentance” (Rom 2:4). Jesus said “repent and believe the good news” (Mark 1:15): turn your mind around, because the kingdom is here. Repentance is real, ongoing and sometimes painful, but it is the joy of waking up, not the dread of grovelling, like the prodigal who rehearsed a speech about being a servant but was interrupted by his father’s embrace.",
    original: "Greek <em>metanoia</em> (μετάνοια), which HELPS Word-studies glosses as literally “a change of mind” (“after-thought”); the verb is <em>metanoeō</em>. Hebrew <em>shuv</em> (שׁוּב), “to turn, return”, the prophets’ call to come back to the LORD. The Hebrew <em>nacham</em> (נָחַם), “to be sorry, relent, comfort oneself”, is also used of God “relenting” from disaster (Jonah 3:10), which shows that a change of mind is part of covenant relationship.",
    refs: ["Mark 1:15", "Rom 2:4", "Luke 15:17-24", "Acts 3:19", "2 Cor 7:9-10", "Acts 11:18", "Joel 2:12-13"],
    note: "Both views agree repentance is a gift of God (Acts 11:18) and a real human turning; the main debate is whether it is a condition for receiving forgiveness or the fruit of discovering a forgiveness already given."
  },
  {
    id: "born-again",
    term: "Born again",
    group: "Salvation",
    legal: "To be born again is to be regenerated by the Holy Spirit, receiving a new heart and new spiritual life, without which no one can see the kingdom of God (John 3:3-7; Titus 3:5). In evangelical usage it usually refers to a definite conversion experience in which a person personally trusts Christ. In Reformed theology regeneration is God’s sovereign work that precedes and produces faith, and its fruit is a changed life that loves God, trusts Christ and turns from sin.",
    relational: "Being born again is being “born from above”: receiving the life of God that comes down to us in Christ by the Spirit (John 3:3, 5). Peter says the Father “caused us to be born again… through the resurrection of Jesus Christ from the dead” (1 Pet 1:3), so in one sense humanity’s new birth happened when Christ rose. We experience it personally when the Spirit awakens us to that life and we begin to live from it. It is less like a legal change of status and more like a baby coming alive to its parent’s face, and that life keeps unfolding throughout our lives as we learn to live as children of God.",
    original: "Greek <em>gennēthē anōthen</em> (γεννηθῇ ἄνωθεν, John 3:3); <em>anōthen</em> can mean “again” or “from above”, and John seems to play on both, since Nicodemus hears “again”. Peter uses <em>anagennaō</em> (ἀναγεννάω), “to beget again” (1 Pet 1:3, 23). Jesus links new birth with “water and the Spirit” (John 3:5), recalling Ezekiel’s promise of clean water, a new heart and a new spirit (Ezek 36:25-27).",
    refs: ["John 3:3-8", "1 Pet 1:3", "1 Pet 1:23", "Titus 3:5", "2 Cor 5:17", "John 1:12-13", "Ezek 36:26"],
    note: "Whether regeneration comes before faith (Reformed), with faith (many evangelicals), through baptism (Orthodox, Catholic, Lutheran), or first in Christ’s resurrection (1 Pet 1:3) is a long-running debate across the church."
  },
  {
    id: "righteousness",
    term: "Righteousness",
    group: "Salvation",
    legal: "Righteousness is perfect conformity to God’s law. God himself is perfectly righteous, and he requires the same of us, which we cannot supply (Rom 3:10). In the gospel, the righteousness of Christ, his perfect obedience, is imputed or credited to believers so that they are counted righteous before God’s court (Rom 4:5-6; Phil 3:9), which is the ground of the believer’s confidence before God.",
    relational: "Righteousness in the Bible is right relationship: being faithful to the covenant and putting things right. God’s righteousness is not only his strict standard but his saving faithfulness, the way he sets right what is wrong (Ps 98:2-3; Isa 46:13). In Christ we do not merely receive a legal credit; we are joined to the One who is our righteousness (1 Cor 1:30) and so we “become the righteousness of God” in him (2 Cor 5:21). Righteousness is therefore relational, restorative and lived out in justice for others (Amos 5:24; Mic 6:8), so a righteous person in Scripture is not only morally clean but someone who sets right what is wrong in the lives of others.",
    original: "Hebrew <em>tsedeq</em> / <em>tsedaqah</em> (צֶדֶק / צְדָקָה), “rightness, righteousness, justice”, often paired with <em>mishpat</em>, justice. Greek <em>dikaiosynē</em> (δικαιοσύνη), which Strong’s glosses as “equity (of character or act)” and “(specially) Christian justification”; the same word means both “righteousness” and “justice”. In Matthew 6:1 “practice your righteousness” uses <em>dikaiosynē</em> for acts of devotion such as almsgiving, prayer and fasting, and in later Hebrew <em>tsedaqah</em> itself came to mean charity to the poor.",
    refs: ["Rom 1:16-17", "Rom 3:21-26", "2 Cor 5:21", "1 Cor 1:30", "Phil 3:9", "Ps 98:2-3", "Isa 46:13", "Mic 6:8"],
    note: "Whether “the righteousness of God” in Romans means a status God gives (Luther), God’s covenant faithfulness (N.T. Wright) or God’s saving, liberating power (Ernst Käsemann) is a major scholarly debate."
  },
  {
    id: "justification",
    term: "Justification",
    group: "Salvation",
    legal: "Justification is God’s once-for-all legal declaration that a sinner is righteous, not because of anything in them, but because Christ’s obedience and satisfaction are imputed to them and received by faith alone (Rom 3:28; 4:5). The Westminster Confession says God justifies “not by infusing righteousness” but “by pardoning their sins, and by accounting and accepting their persons as righteous” (WCF 11.1). It is the article by which, Reformers said, the church stands or falls, because any righteousness of our own would leave us uncertain, while Christ’s righteousness is complete.",
    relational: "Justification is God putting us right with himself and with one another. It is God’s verdict, but a verdict of a Father who is setting a broken world right, not only a judge balancing books (Rom 4:25; 5:18). Paul says that through Christ’s one act of righteousness came “justification of life for all people” (Rom 5:18), and that Christ was raised for our justification (Rom 4:25). So justification flows from union with the risen Christ: we are right with God because we are in the one who is right with God, and faith is how we come to share and enjoy it (Gal 2:16-20), so that justification is never a cold legal file but a living relationship.",
    original: "Greek <em>dikaioō</em> (δικαιόω), “to justify, declare or make righteous, vindicate”; Hebrew <em>tsadaq</em> (צָדַק) in its causative form, “to declare right, vindicate” (Isa 53:11). Paul’s phrase <em>pistis Christou</em> (Gal 2:16) can be read “faith in Christ” or “the faithfulness of Christ”, a much-debated question. Paul’s great text Rom 4:5 speaks of God “who justifies the ungodly”, the same verb the Septuagint uses in Exod 23:7 where God says he will not justify the wicked, a tension Paul resolves in Christ.",
    refs: ["Rom 3:21-28", "Rom 4:5", "Rom 4:25", "Rom 5:1", "Rom 5:18", "Gal 2:16-20", "Isa 53:11", "Jas 2:24"],
    note: "Justification by faith is shared ground; the debates are over whether it is purely forensic or also transformative, how it relates to union with Christ (which Calvin himself made central), and how to read <em>pistis Christou</em>."
  },
  {
    id: "faith",
    term: "Faith",
    group: "Salvation",
    legal: "Saving faith is the God-given trust by which a sinner receives and rests upon Christ alone for salvation (WCF 14.2 summarised). It includes knowledge of the gospel, agreement that it is true and personal trust in Christ (often described as <em>notitia</em>, <em>assensus</em> and <em>fiducia</em>). Faith is the instrument, not the ground, of justification: we are saved through faith, not because of faith, so that even our trust is God’s gift, leaving no room for boasting.",
    relational: "Faith is trust: resting in the faithfulness of God revealed in Jesus. It is not a work we do to activate grace, but our awakening to and participation in the faith of Jesus himself, who trusted the Father on our behalf (Gal 2:20, “the faith of the Son of God”, KJV). We move from straining to have enough “faith toward God” to relaxing into the faithfulness of God. Faith works through love (Gal 5:6) and grows like a mustard seed, because it is relational, not a quantity of mental certainty (Matt 17:20), and the smallest trust in a faithful God is enough to move mountains.",
    original: "Greek <em>pistis</em> (πίστις), “faith, trust, faithfulness”; Hebrew <em>’emunah</em> (אֱמוּנָה), “firmness, steadiness, faithfulness” (Hab 2:4), from the root of “amen”. The Hebrew <em>’aman</em> lies behind “Abraham believed the LORD” (Gen 15:6), literally “Abraham leaned firmly on” or “found the LORD firm”, a picture of relying on someone trustworthy.",
    refs: ["Eph 2:8", "Gal 2:20", "Gal 5:6", "Heb 11:1-6", "Hab 2:4", "Rom 4:18-21", "Heb 12:2", "Mark 9:24"],
    note: "Because <em>pistis</em> means both “faith” and “faithfulness”, the old KJV rendering “the faith of the Son of God” (Gal 2:20) has been revived by many scholars, though others defend “faith in the Son of God”."
  },
  {
    id: "forgiveness",
    term: "Forgiveness",
    group: "Salvation",
    legal: "Forgiveness is God’s pardon of a sinner’s guilt and his release from the penalty they deserve, made possible because Christ paid that penalty (Eph 1:7). It is received through repentance and faith, and the believer’s ongoing sins are forgiven as they confess them (1 John 1:9). God forgives justly because the debt has been paid, not because he overlooks it, and so forgiveness is a gift of perfect justice as well as perfect mercy.",
    relational: "Forgiveness is release: God letting go of our sins, sending them away and refusing to hold them against us (Ps 103:12; 2 Cor 5:19). Jesus forgave freely before any sacrifice, to paralysed men and sinful women, and from the cross he forgave his executioners without their asking (Mark 2:5; Luke 7:48; 23:34). So forgiveness is not something the cross bought from an unwilling God, but something the cross reveals from a God who has always been willing. We receive it, rejoice in it and pass it on to others (Col 3:13), becoming people who release others as we have been released.",
    original: "Greek <em>aphesis</em> (ἄφεσις), “release, letting go, sending away”, the word Jesus uses for freedom to captives (Luke 4:18); verb <em>aphiēmi</em> (ἀφίημι). Hebrew <em>salach</em> (סָלַח), “to forgive, pardon”, and <em>nasa’</em> (נָשָׂא), “to lift, carry away” (Ps 32:1). In the Lord’s Prayer Matthew uses <em>opheilēmata</em> (ὀφειλήματα), “debts” (Matt 6:12), and Luke uses <em>hamartias</em>, “sins” (Luke 11:4), so both legal and relational pictures sit side by side in Jesus’ own teaching.",
    refs: ["Mark 2:5-10", "Luke 7:47-48", "Luke 23:34", "Eph 1:7", "Col 2:13-14", "1 John 1:9", "Ps 103:10-12", "Col 3:13"],
    note: "Forgiveness from God and forgiveness between people are linked in the Lord’s Prayer (Matt 6:12); both views agree that forgiving someone does not require pretending harm did not happen or returning to an unsafe situation."
  },
  {
    id: "reconciliation",
    term: "Reconciliation",
    group: "Salvation",
    legal: "Reconciliation is the restoration of peace between God and sinners, made possible when Christ’s death removed the barrier of sin and God’s just hostility toward it (Rom 5:10; Col 1:21-22). It is objectively accomplished at the cross and subjectively received when a sinner responds to the call, “be reconciled to God” (2 Cor 5:20). The legal view usually says both sides needed reconciling: humanity’s rebellion and God’s righteous wrath, so that the cross both removes God’s judicial hostility and overcomes human rebellion.",
    relational: "Reconciliation is the heart of the gospel: “God was in Christ reconciling the world to himself, not counting their trespasses against them” (2 Cor 5:19). In the New Testament God is always the subject who reconciles and we, or the world, are the ones reconciled; God never needs to be reconciled to us. It is cosmic in scope, reaching “all things, whether on earth or in heaven” (Col 1:20), and it overflows into healed relationships between people and peoples (Eph 2:14-16). Our task is to announce it and live it as ambassadors (2 Cor 5:20), calling every person to receive what God has already done for them.",
    original: "Greek <em>katallassō</em> (καταλλάσσω), which Thayer’s lexicon says properly means “to change, exchange, as coins for others of equal value”, and so “to reconcile (those who are at variance)”; noun <em>katallagē</em> (καταλλαγή). Colossians 1:20 uses the stronger compound <em>apokatallassō</em> (ἀποκαταλλάσσω), “to reconcile completely”, for God reconciling all things to himself through the blood of the cross.",
    refs: ["2 Cor 5:17-21", "Rom 5:10-11", "Col 1:19-22", "Eph 2:14-16", "Matt 5:23-24", "1 Cor 7:11"],
    note: "Both views agree reconciliation is God’s initiative and must be received; they differ on whether God’s side also needed changing, and Thayer notes that the passive could describe one party simply ceasing to be angry and receiving the other back into favour."
  },
  {
    id: "adoption",
    term: "Adoption",
    group: "Salvation",
    legal: "Adoption is the act of God’s free grace by which those who are justified are received into the number of God’s children, given the Spirit of adoption and all the privileges of sons and daughters (WCF 12.1; Gal 4:4-7). It follows justification: having been declared righteous, believers are welcomed into the family. It applies only to believers; by nature people are “children of wrath” (Eph 2:3), and so adoption gives believers a family identity and a sure inheritance.",
    relational: "Adoption is the Father’s eternal plan to share his life with us as sons and daughters in the Son (Eph 1:4-5). The Son became what we are so that we could share his relationship with the Father, crying “Abba, Father” by his Spirit (Gal 4:6; Rom 8:15). J.B. Torrance and Baxter Kruger stress that adoption is not an afterthought to legal acquittal but the very purpose of creation: we were made to be included in the Trinity’s love. It is less like a court changing our file and more like coming home to the family we were always meant for (Luke 15:22-24), and the Spirit who cries “Abba” in us is the Spirit of the Son, so we share his own place at the Father’s table.",
    original: "Greek <em>huiothesia</em> (υἱοθεσία), literally “son-placing”, a Roman legal term for adopting an heir; it occurs five times, all in Paul (Rom 8:15, 23; 9:4; Gal 4:5; Eph 1:5). In Roman law an adopted son received a new name, had old debts cancelled and became a full heir, a background often described by commentators and probably familiar to Paul’s readers.",
    refs: ["Eph 1:4-5", "Gal 4:4-7", "Rom 8:14-17", "Rom 8:23", "John 1:12", "1 John 3:1-2", "Luke 15:22-24"],
    note: "Adoption is one place where the legal and relational traditions meet warmly; Reformed writers such as J.I. Packer (<em>Knowing God</em>) called it the highest privilege the gospel offers."
  },
  {
    id: "election",
    term: "Election",
    group: "Salvation",
    legal: "Election is God’s eternal, sovereign choice, before creation, of particular individuals to be saved, not based on foreseen faith or merit but on his good pleasure (Eph 1:4-5; Rom 9:11-16). In Reformed theology the elect are certainly saved, while those passed over are left to the just consequences of their sin. Arminian evangelicals instead see election as based on God’s foreknowledge of who would believe, though both camps agree that salvation rests ultimately on God’s initiative and not ours.",
    relational: "Election is God’s choice of humanity in Christ. Karl Barth argued that Jesus is both the electing God and the elected human, so that God’s choosing is first a choosing of Christ and of all humanity in him (Eph 1:4, “chose us in him”). In Scripture election is usually a calling for the sake of others, as Abraham was chosen so that all families of the earth would be blessed (Gen 12:3). God’s choosing is therefore not a lottery of the few but the guarantee that his love has the first and last word for all (Rom 11:32), and the chosen are chosen in order to carry blessing to everyone else.",
    original: "Greek <em>eklegomai</em> (ἐκλέγομαι), “to choose out”, <em>eklektos</em> (ἐκλεκτός), “chosen”, <em>eklogē</em> (ἐκλογή), “choice, election”. Hebrew <em>bachar</em> (בָּחַר), “to choose” (Deut 7:6-8). The Father calls Jesus “my Chosen One” (<em>ho eklelegmenos</em>, Luke 9:35), which supports reading election as first of all about Christ, and of others in him.",
    refs: ["Eph 1:3-11", "Rom 9:10-16", "Rom 11:28-32", "Gen 12:1-3", "Deut 7:6-8", "1 Pet 2:9", "John 15:16"],
    note: "Election has divided Calvinists and Arminians for centuries; Barth’s Christ-centred reading (<em>Church Dogmatics</em> II/2) is admired by many but criticised by Reformed and evangelical theologians as leaning toward universalism."
  },

  // ================================================================ LIFE
  {
    id: "holiness",
    term: "Holiness",
    group: "Life",
    legal: "Holiness is God’s absolute moral purity and his separation from all sin; he is “holy, holy, holy” (Isa 6:3), the only attribute Scripture repeats three times in this way. Because God is holy he cannot tolerate sin, and he calls his people to be holy as he is holy (1 Pet 1:15-16). Without holiness, Hebrews warns, no one will see the Lord (Heb 12:14), so the legal gospel calls believers to separate from sin and pursue lives of moral purity.",
    relational: "Holiness is the otherness of God’s love: he is unlike us not because he is cold and distant, but because his love is so pure, faithful and self-giving. When Jesus, the Holy One of God, touched lepers and ate with sinners, holiness flowed outward and made the unclean clean instead of being contaminated (Mark 1:40-42). Our holiness is first a gift, sharing in his holiness (Heb 12:10; 1 Cor 1:2), and then a life of wholeness that grows as we live from union with him. Holy people are not those who keep their distance from the broken, but those through whom God’s healing love moves, and they look more like Jesus at a table of sinners than like a fortress keeping sinners out.",
    original: "Hebrew <em>qadosh</em> (קָדוֹשׁ), “holy, set apart”, and <em>qodesh</em> (קֹדֶשׁ), “holiness, sacredness”. Greek <em>hagios</em> (ἅγιος), “holy”, the word behind “saints” (<em>hagioi</em>, “holy ones”), which Paul uses for ordinary believers (1 Cor 1:2). Paul calls believers <em>hagioi</em> even in Corinth, a deeply troubled church (1 Cor 1:2), which shows that holiness is first a gift of belonging before it is an achievement.",
    refs: ["Isa 6:1-8", "Lev 19:2", "1 Pet 1:15-16", "Heb 12:10-14", "Mark 1:40-42", "1 Cor 1:2", "Hos 11:9"],
    note: "Hosea 11:9 is striking for both views: God refuses to act in fierce anger precisely because “I am God and not man, the Holy One in your midst”, linking holiness with mercy."
  },
  {
    id: "sanctification",
    term: "Sanctification",
    group: "Life",
    legal: "Sanctification is the lifelong work of God’s grace by which believers are renewed in the whole person after God’s image and enabled more and more to die to sin and live to righteousness (Westminster Shorter Catechism, Q.35). Unlike justification, which is complete at once, sanctification is progressive and never perfect in this life. Believers cooperate through Scripture, prayer, the sacraments, accountability and discipline, until glorification makes the believer perfectly holy at Christ’s appearing.",
    relational: "Sanctification is becoming in experience who we already are in Christ. Christ himself “became for us… sanctification” (1 Cor 1:30), so holiness is not a ladder we climb but a life we grow into, like a child growing into their family likeness. The Spirit transforms us as we behold the Lord’s glory, “from glory to glory” (2 Cor 3:18), and as we renew our minds to see ourselves rightly (Rom 12:2; 6:11). It is a real process with real effort, but the effort is the cooperation of love, not anxious self-improvement (Phil 2:12-13), trusting the One who began a good work in us to bring it to completion (Phil 1:6).",
    original: "Greek <em>hagiasmos</em> (ἁγιασμός), which Strong’s glosses as “purification”, “(the state) purity”; HELPS describes it as “the believer being progressively transformed by the Lord into His likeness”. The verb is <em>hagiazō</em> (ἁγιάζω), “to make holy, set apart”. Paul’s prayer that God would sanctify believers “completely” (<em>holoteleis</em>, ὁλοτελεῖς, 1 Thess 5:23) includes spirit, soul and body, so sanctification is meant to reach the whole person.",
    refs: ["1 Cor 1:30", "2 Cor 3:18", "Rom 6:11-22", "Rom 12:1-2", "Phil 2:12-13", "1 Thess 4:3-7", "1 Thess 5:23-24", "Heb 10:10-14"],
    note: "Hebrews says believers “have been sanctified” once for all (Heb 10:10) and are also “being sanctified” (Heb 10:14), so both frameworks speak of a holiness given and a holiness grown."
  },
  {
    id: "worship",
    term: "Worship",
    group: "Life",
    legal: "Worship is the creature’s proper response of reverence, praise and obedience to the holy God, offered as he commands in Scripture (John 4:24). Many Reformed churches follow the “regulative principle”, worshipping only in ways God has commanded, such as preaching, prayer, singing, sacraments and giving. Acceptable worship is offered through Christ the mediator, since sinners cannot approach God on their own, and through him the worship of believers is acceptable to God.",
    relational: "Worship is joining the love the Son and the Spirit already offer to the Father. J.B. Torrance described Christian worship (paraphrase) as the gift of sharing, by the Spirit, in the incarnate Son’s own communion with the Father, rather than something we produce by our own effort. Jesus is our worship leader, the true high priest who sings the Father’s praise among his brothers and sisters (Heb 2:12; 8:1-2). Worship therefore includes songs and liturgy, but it is also the offering of our whole embodied life (Rom 12:1), and it is joy, rest and gratitude rather than performance, until the whole creation joins the song of Revelation 5:13.",
    original: "Greek <em>proskyneō</em> (προσκυνέω), “to bow down, pay homage”; <em>latreuō</em> (λατρεύω), “to serve, render worship” (Rom 12:1). Hebrew <em>hishtachavah</em> (הִשְׁתַּחֲוָה), “to bow down, prostrate oneself”. Romans 12:1 calls the offering of our bodies our <em>logikē latreia</em> (λογικὴ λατρεία), translated “reasonable” or “spiritual” worship, meaning worship that fits the logic of the gospel.",
    refs: ["John 4:23-24", "Rom 12:1", "Heb 2:11-12", "Heb 8:1-2", "Heb 13:15", "Ps 95:1-7", "Rev 4:8-11"],
    note: "J.B. Torrance’s <em>Worship, Community and the Triune God of Grace</em> (1996) contrasts “unitarian” worship (what we do) with “Trinitarian” worship (sharing in what Christ does), a distinction many evangelicals have found helpful."
  },
  {
    id: "prayer",
    term: "Prayer",
    group: "Life",
    legal: "Prayer is the offering of our desires to God in the name of Christ, with confession of our sins and thankful acknowledgment of his mercies (Westminster Shorter Catechism, Q.98). Because of Christ’s mediation, believers have access to the throne of grace (Heb 4:16). Prayer is a duty and a privilege, and God uses it as a means to accomplish his purposes, so believers pray both in obedience and in dependent trust.",
    relational: "Prayer is conversation within a family. Jesus taught us to pray “Our Father” and invites us into his own intimacy with the Father, crying “Abba” by the Spirit (Matt 6:9; Gal 4:6). The Spirit prays in us when we do not know how to pray (Rom 8:26), and Jesus continues to intercede for us (Heb 7:25), so prayer is joining a conversation already going on in God. It includes asking, lament, thanksgiving, silence and simply being with God, as Brother Lawrence described “practising the presence of God”, so prayer is less about getting God to act and more about being drawn into what Love is already doing.",
    original: "Greek <em>proseuchē</em> (προσευχή), “prayer”, and <em>deēsis</em> (δέησις), “petition, request”. Hebrew <em>tefillah</em> (תְּפִלָּה), “prayer”. Jesus’ Aramaic <em>Abba</em> (Mark 14:36) is the intimate word for “father”. Paul’s “pray without ceasing” (<em>adialeiptōs</em>, ἀδιαλείπτως, 1 Thess 5:17) uses a word for something constantly recurring, so it describes an ongoing posture of prayer rather than literally unbroken speech.",
    refs: ["Matt 6:5-13", "Mark 14:36", "Rom 8:15", "Rom 8:26-27", "Heb 4:16", "Heb 7:25", "Phil 4:6-7", "1 Thess 5:17"],
    note: "The popular claim that <em>Abba</em> simply means “Daddy” is an overstatement: scholars such as James Barr showed adults also used it, but it is still a warm, family word."
  },
  {
    id: "obedience",
    term: "Obedience",
    group: "Life",
    legal: "Obedience is conformity to God’s revealed will in his commandments, the proper response of grateful believers who have been saved by grace (John 14:15). It does not earn salvation, but it is the necessary evidence of genuine faith (Jas 2:17). Christ’s own perfect obedience, active and passive, is credited to believers for justification, while their obedience flows from sanctification, and the believer obeys out of gratitude for grace rather than to gain it.",
    relational: "Obedience is listening: hearing the voice of love and following it. Jesus’ obedience flowed from his oneness with the Father (John 5:19; 8:29), and our obedience flows from union with him, as fruit grows from a branch abiding in the vine (John 15:4-5). Paul calls it “the obedience of faith” (Rom 1:5), obedience that springs from trust. It is not fearful compliance to avoid punishment, but the freedom of a child who knows they are loved and so wants what the Father wants (1 John 4:18-19), and when we fail, we return to the same Father who taught us to walk.",
    original: "Greek <em>hypakoē</em> (ὑπακοή), from <em>hypo</em> (“under”) and <em>akouō</em> (“hear”): “listening under”, attentive hearing. Hebrew <em>shama‘</em> (שָׁמַע), “to hear, listen, obey” (Deut 6:4, the Shema), with no separate Hebrew word for “obey”. Jesus’ own obedience is described with the same word (Rom 5:19; Heb 5:8, “he learned obedience”), which shows that obedience is part of sharing the Son’s life, not a servant’s duty imposed from outside.",
    refs: ["John 14:15", "John 15:4-10", "John 5:19", "Rom 1:5", "Deut 6:4-6", "1 John 4:18-19", "Phil 2:8", "Jas 2:17"],
    note: "Both views agree true faith produces obedience; the difference is whether obedience is framed mainly as duty and evidence (legal) or as the natural expression of a new life and identity (relational)."
  },
  {
    id: "eternal-life",
    term: "Eternal life",
    group: "Life",
    legal: "Eternal life is the gift God gives to believers, beginning at conversion and continuing forever in his presence, the opposite of eternal punishment (John 3:16; Rom 6:23). In popular evangelical language it is often equated with “going to heaven when you die”. Its certainty rests on Christ’s finished work, and it can be received now by faith (1 John 5:11-13), so that believers can know, not merely hope, that they have it.",
    relational: "Jesus defined eternal life not as endless time but as relationship: “This is eternal life, that they should know you, the only true God, and him whom you sent, Jesus Christ” (John 17:3). It is the life of the age to come, the very life of the Trinity, breaking into the present (John 10:10). It is not first a reward after death, but a quality of life that begins now and death cannot end (John 11:25-26). Eternal life is sharing the Son’s knowing of the Father, which is why it overflows in love (1 John 3:14), and it is already ours as we abide in the Son who is himself “the resurrection and the life”.",
    original: "Greek <em>zōē aiōnios</em> (ζωὴ αἰώνιος). <em>Aiōnios</em> is related to <em>aiōn</em>, “age”, and in Jewish usage often means “belonging to the age (to come)”, so the phrase emphasises the kind of life, not only its length. Daniel 12:2 is the clearest Old Testament text on “everlasting life” (<em>chayyei ‘olam</em>, חַיֵּי עוֹלָם), where <em>‘olam</em> means a long or unending age.",
    refs: ["John 17:3", "John 3:16", "John 10:10", "John 11:25-26", "1 John 5:11-13", "Rom 6:23", "1 John 3:14"],
    note: "The meaning of <em>aiōnios</em> matters for the debate on hell as well, because Matt 25:46 uses the same adjective for “eternal punishment” and “eternal life”; universalists and traditionalists draw opposite conclusions from that parallel."
  },

  // ================================================================ CHURCH & MISSION
  {
    id: "the-church",
    term: "The church",
    group: "Church & mission",
    legal: "The church is the community of those who have been saved through faith in Christ, called out of the world to worship God, hear the preached Word, receive the sacraments and live under biblical discipline (Acts 2:41-47). The invisible church consists of all the elect; the visible church consists of those who profess faith together with their children (WCF 25.1-2 summarised). Its central mission is to proclaim the gospel and make disciples, and its faithfulness is measured by the pure preaching of the Word and right administration of the sacraments.",
    relational: "The church is the body of Christ, the family of the Father and the temple of the Spirit (1 Cor 12:27; Eph 2:19-22). It is the part of humanity that has woken up to what God has done for all humanity, and it exists as a sign and foretaste of the reconciled world (Eph 3:10). It is less a building or an institution than a people sharing the life of the Trinity in shared meals, gifts, forgiveness and mission (Acts 2:42-47). The church is not the club of the saved set against the world, but the firstfruits of what God is doing for the world (Jas 1:18), and its shared table is a foretaste of the feast God is preparing for all peoples (Isa 25:6-8).",
    original: "Greek <em>ekklēsia</em> (ἐκκλησία), “assembly, gathering”, used in the Greek Old Testament for the assembly of Israel (Hebrew <em>qahal</em>, קָהָל). The popular etymology “the called-out ones” is often overpressed; in ordinary use the word simply meant an assembly. Jesus’ words “I will build my church” (Matt 16:18) are one of only two places the word <em>ekklēsia</em> appears in the Gospels (with Matt 18:17).",
    refs: ["Matt 16:18", "Acts 2:42-47", "1 Cor 12:12-27", "Eph 2:19-22", "Eph 3:10", "Col 1:18", "1 Pet 2:9-10"],
    note: "Both frameworks see the church as Christ’s body; Protestant, Catholic and Orthodox traditions differ sharply on how the church is structured and where its boundaries lie."
  },
  {
    id: "baptism",
    term: "Baptism",
    group: "Church & mission",
    legal: "Baptism is an ordinance or sacrament commanded by Christ, signifying the believer’s union with Christ in his death and resurrection, the washing away of sin and entrance into the visible church (Matt 28:19; Rom 6:3-4). Baptists hold that it should follow personal faith and be by immersion, while Presbyterians and others baptise the children of believers as a sign of the covenant. In most evangelical teaching baptism is an outward sign of an inward reality, not the means of salvation itself, though it is a solemn command that every believer should obey.",
    relational: "Baptism is the enactment of our inclusion in Christ’s own baptism, death and resurrection. At the Jordan Jesus stood with sinners and heard the Father say, “You are my beloved Son” (Mark 1:11), and in our baptism that same word is spoken over us (Gal 3:26-27). The relational gospel stresses that baptism is first God’s act and God’s announcement, not mainly our performance or decision. It is a drowning of the old self and a rising into new life, a family welcome and a lifelong identity (Rom 6:3-11; Col 2:12), so we look back to our baptism not as a past decision but as a present word of belonging.",
    original: "Greek <em>baptizō</em> (βαπτίζω), “to dip, immerse, wash”, used for washing hands and dishes as well as ritual immersion (Mark 7:4; Luke 11:38). Jesus also spoke of his coming death as a baptism (Mark 10:38; Luke 12:50), which links Christian baptism to being plunged into his death and raised with him.",
    refs: ["Matt 3:13-17", "Mark 1:9-11", "Matt 28:19", "Rom 6:3-11", "Gal 3:26-28", "Col 2:11-12", "Acts 2:38", "1 Pet 3:21"],
    note: "Infant versus believer’s baptism, and whether baptism is a sign or a means of grace, are among the oldest disagreements in the church; both views here agree that baptism unites us with Christ’s death and resurrection."
  },
  {
    id: "great-commission",
    term: "The Great Commission",
    group: "Church & mission",
    legal: "The Great Commission is Jesus’ command to his followers to go into all the world, preach the gospel and make disciples of all nations, baptising and teaching them (Matt 28:18-20; Mark 16:15). In much evangelical teaching it is the church’s primary task, because people who die without Christ face eternal judgment. Personal evangelism, missions and church planting are its main expressions, all undertaken with urgency because eternity is at stake.",
    relational: "The Great Commission begins with Jesus’ authority and ends with his presence: “All authority has been given to me… I am with you always” (Matt 28:18, 20). Its heart is making disciples: learners who share Jesus’ life, are immersed into the name of Father, Son and Spirit, and learn to live his way of love (Matt 28:19-20). It is sharing good news that is already true for everyone, as ambassadors of reconciliation, rather than selling a ticket out of hell (2 Cor 5:19-20). It goes hand in hand with the Great Commandment: love God and neighbour (Matt 22:37-40), so that disciples are formed by seeing that love lived out in community, not only by hearing a presentation.",
    original: "The one main imperative in Matt 28:19 is <em>mathēteusate</em> (μαθητεύσατε), “make disciples”. “Go” translates the participle <em>poreuthentes</em> (πορευθέντες), “having gone” or “as you go”, which most grammarians think carries imperatival force alongside the main verb. The phrase “the name of the Father and of the Son and of the Holy Spirit” uses one singular “name” (<em>to onoma</em>, τὸ ὄνομα) for all three, which the church fathers read as a witness to the Trinity.",
    refs: ["Matt 28:16-20", "Mark 16:15", "Luke 24:46-49", "Acts 1:8", "John 20:21", "2 Cor 5:18-20", "Matt 22:37-40"],
    note: "The name “Great Commission” is a later label, popularised in modern missions; the Lausanne Covenant (1974) affirmed that evangelism and social responsibility both belong to Christian duty."
  },

  // ================================================================ END
  {
    id: "heaven",
    term: "Heaven",
    group: "End",
    legal: "Heaven is the dwelling place of God, where believers go at death to be with Christ and where they will enjoy God forever (Phil 1:23; 2 Cor 5:8). In popular evangelical preaching, the goal of salvation is often summed up as “going to heaven” instead of hell. Reformed teaching also affirms the bodily resurrection and the new heavens and new earth as the final state, where believers will see God face to face.",
    relational: "Heaven is where God’s will is fully done, the realm of his presence, and the goal is not that we escape to heaven but that heaven comes to earth (Matt 6:10; Rev 21:2-3). At death believers are “with Christ” (Phil 1:23), but that is a resting place, not the final destination; the final hope is resurrection and a renewed creation where God dwells with people. N.T. Wright summarised this as “life after life after death”. Heaven is also near now: in Christ we are already seated in the heavenly places (Eph 2:6), and wherever love reigns, heaven touches earth, so the Christian hope is not leaving the world behind but seeing heaven and earth finally joined.",
    original: "Hebrew <em>shamayim</em> (שָׁמַיִם), a plural-form word meaning “sky, heavens”; Greek <em>ouranos</em> (οὐρανός), “sky, heaven”. Both words describe the sky as well as God’s realm. Paul’s phrase “our citizenship is in heaven” (Phil 3:20) uses <em>politeuma</em> (πολίτευμα), “commonwealth, citizenship”, a word readers in the Roman colony of Philippi would have heard as citizens representing their home city abroad, waiting not to leave but for their Saviour to come from there.",
    refs: ["Matt 6:9-10", "Phil 1:21-23", "2 Cor 5:1-8", "Eph 2:6", "Rev 21:1-4", "Phil 3:20-21", "Col 3:1-4"],
    note: "Both traditions officially teach the resurrection and new creation as the final hope; the gap is mostly between that teaching and the popular picture of disembodied souls in the clouds."
  },
  {
    id: "hell",
    term: "Hell",
    group: "End",
    legal: "Hell is the place of eternal, conscious punishment for those who die unrepentant, where they experience God’s just wrath forever (Matt 25:46; Rev 14:10-11). It is the necessary outcome of God’s holiness: an infinite offence against an infinite God deserves an unending penalty. Jesus himself spoke more about hell than anyone, the legal view stresses, warning so that people would flee to him, and its reality makes the free offer of the gospel all the more precious.",
    relational: "Within the relational stream there are different views, but most see hell as real and serious while rejecting the picture of an eternal torture chamber designed by God. Some hold that hell is the experience of God’s love by those who resist it, like the same sun that softens wax and hardens clay (an image found in Orthodox writers). Hopeful universalists, from Gregory of Nyssa to George MacDonald, David Bentley Hart and Robin Parry, read judgment as purifying fire that aims to restore, and hope that in the end God will be “all in all” (1 Cor 15:28). What all agree on is that God’s fire is the fire of love, and that his judgments, even in hell, do not cease to be the judgments of Jesus, whose love never gives up on the lost sheep until it is found (Luke 15:4).",
    original: "Hebrew <em>she’ol</em> (שְׁאוֹל), the shadowy realm of the dead; Greek <em>hadēs</em> (ᾅδης), its counterpart. <em>Geenna</em> (γέεννα), from the Valley of Hinnom outside Jerusalem, appears twelve times in the New Testament, mostly from Jesus. <em>Tartaroō</em> (2 Pet 2:4) is used once. The <em>kolasis</em> of Matt 25:46 is translated “punishment”; some argue it can carry the sense of corrective chastisement, a debated claim. The fire language draws on Old Testament images like Isaiah 66:24, and Jesus’ hearers knew Hinnom as the place of child sacrifice condemned by the prophets (Jer 7:31).",
    refs: ["Matt 25:41-46", "Mark 9:43-48", "Luke 16:19-31", "Rev 14:10-11", "Rev 20:14-15", "1 Cor 15:22-28", "Lam 3:31-33"],
    note: "Christians have held three main views (eternal conscious punishment, annihilation/conditional immortality, and universal restoration); the 553 condemnations targeted a particular Origenist system, and whether they condemn universal restoration as such is debated."
  },
  {
    id: "judgment",
    term: "Judgment",
    group: "End",
    legal: "Judgment is God’s righteous evaluation of every person according to his law, culminating in the Last Judgment, when Christ will judge the living and the dead and assign each to eternal life or eternal punishment (2 Cor 5:10; Rev 20:11-15). Believers will not be condemned, because Christ bore their judgment, but they will give account and receive rewards. Unbelievers will be judged according to their works and justly condemned, and this truth gives urgency to the call to repent.",
    relational: "Judgment is God putting the world right. In the Bible, the coming of the Judge is good news: the trees and seas sing for joy because he comes to judge the earth with righteousness (Ps 96:11-13). The Judge is Jesus, the one who died for his judges (John 5:22; Acts 17:31), so judgment is the light of truth exposing everything, burning away what is false and healing what is true (1 Cor 3:12-15). It is real and searching, but its aim is restoration, not revenge, because God’s justice is restorative (Isa 1:26-27), and the One who will judge the world has already shown at the cross how he judges: by bearing the sin of the guilty and forgiving them.",
    original: "Hebrew <em>mishpat</em> (מִשְׁפָּט), “justice, judgment, right order”, from <em>shaphat</em> (שָׁפַט), “to judge, govern, vindicate”; the “judges” of Israel were mostly deliverers. Greek <em>krisis</em> (κρίσις) and <em>krima</em> (κρίμα), “judgment, decision, verdict”. In John’s Gospel <em>krisis</em> often means the moment of decision when light comes into the world and people respond to it (John 3:19), so judgment is already happening in how we respond to Jesus.",
    refs: ["Ps 96:10-13", "John 5:22-27", "John 12:31-32", "Acts 17:31", "2 Cor 5:10", "1 Cor 3:12-15", "Rev 20:11-15", "Isa 1:26-27"],
    note: "Both views agree that there will be a real final judgment by Christ; Christopher Marshall (<em>Beyond Retribution</em>, 2001) argued that biblical justice is chiefly restorative, a view traditionalists answer from texts like 2 Thess 1:6-9."
  },
  {
    id: "second-coming",
    term: "The second coming",
    group: "End",
    legal: "The second coming is the personal, visible, bodily return of Jesus Christ at the end of the age to raise the dead, judge the world and bring his kingdom in fullness (Acts 1:11; 1 Thess 4:16-17). Many evangelicals hold dispensational views with a rapture and tribulation, while Reformed Christians are often amillennial or postmillennial. All agree it should motivate holy living and urgent evangelism (2 Pet 3:11-12), since believers do not know the day or the hour.",
    relational: "The second coming is the appearing of the same Jesus, the unveiling of the One who is already with us and already Lord (Col 3:4; 1 John 3:2). It is not God finally losing patience and switching from mercy to vengeance, but the full revealing of the love shown at the cross, the King arriving to set his world right. Paul pictures believers going out to “meet” the Lord as citizens met an arriving emperor and escorted him into the city (1 Thess 4:17), so the hope is Christ coming to renew the earth, not removing us from it. Its effect is hope, not fear (Titus 2:13), the hope that one day every tear will be wiped away by the hand of the Lamb who was slain (Rev 7:17).",
    original: "Greek <em>parousia</em> (παρουσία), “presence, arrival”, used of royal visits; <em>epiphaneia</em> (ἐπιφάνεια), “appearing”; <em>apokalypsis</em> (ἀποκάλυψις), “unveiling”. The “meeting” of 1 Thess 4:17 is <em>apantēsis</em> (ἀπάντησις), often used of a delegation going out to greet a visiting dignitary. The early church’s Aramaic prayer <em>Marana tha</em> (1 Cor 16:22), “Our Lord, come!”, shows that longing for his coming was part of ordinary worship from the very beginning.",
    refs: ["Acts 1:11", "1 Thess 4:13-18", "Titus 2:11-14", "Col 3:4", "1 John 3:2-3", "Heb 9:28", "Rev 22:20"],
    note: "Whether the <em>apantēsis</em> background implies Christ’s return to earth with his people is a common scholarly reading but still debated, and preterist, futurist and other interpretations differ widely on details."
  },
  {
    id: "new-creation",
    term: "The new creation",
    group: "End",
    legal: "The new creation describes both the believer’s new life in Christ (2 Cor 5:17) and the new heavens and new earth that God will create after the final judgment (Rev 21:1). Reformed theology stresses that the present creation will be purified and renewed, while some popular evangelical teaching has pictured it as destroyed and replaced. In the new creation the redeemed will enjoy God forever, free from sin and suffering, and every tear will be wiped away by God himself (Rev 21:4).",
    relational: "The new creation began on Easter morning: the risen body of Jesus is the first piece of the renewed universe, and “if anyone is in Christ, there is a new creation” (2 Cor 5:17). God does not throw away his first creation but heals and fulfils it: “Behold, I am making all things new” (Rev 21:5), not “all new things”. Creation itself waits with eager longing to be set free into the glorious freedom of God’s children (Rom 8:19-21). Every act of healing, justice, beauty and love done in Christ now is a seed of that coming world (1 Cor 15:58), and the leaves of the tree of life in that city are “for the healing of the nations” (Rev 22:2).",
    original: "Greek <em>kainē ktisis</em> (καινὴ κτίσις), “new creation” (2 Cor 5:17; Gal 6:15). Some popular teachers say <em>kainos</em> always means “new in quality” as opposed to <em>neos</em>, “new in time”; that distinction is a tendency, not a fixed rule. Jesus’ word for the coming renewal in Matt 19:28 is <em>palingenesia</em> (παλιγγενεσία), “regeneration, new genesis”, the same word Titus 3:5 uses for personal new birth.",
    refs: ["2 Cor 5:17", "Gal 6:15", "Rom 8:19-23", "Rev 21:1-5", "Isa 65:17-25", "Col 1:15-20", "1 Cor 15:20-28", "1 Cor 15:58"],
    note: "A Romans 8:19 reading of creation awaiting the revealing of God’s children is distinct from the 1940s–50s “Manifest Sons of God” Latter Rain movement, and both evangelical and relational writers increasingly affirm a renewed rather than destroyed earth."
  }
];

